112.     /// <summary>
113.     /// Converts a number to its metric representation using the specified formatting options.
114.     /// </summary>
115.     /// <param name="input">The number to convert.</param>
116.     /// <param name="formats">Formatting options controlling symbol vs name and scale.</param>
117.     /// <param name="decimals">Optional number of decimal places to round to.</param>
118.     /// <returns>A string with the metric representation (e.g., "1.5k" or "1.5 kilo").</returns>
119.     /// <example>
120.     /// <code>
121.     /// 1500.ToMetric() => "1.5k"
122.     /// 1500.ToMetric(MetricFormat.None) => "1.5 kilo"
123.     /// 2500000.ToMetric(MetricFormat.UseSymbol) => "2.5M"
124.     /// </code>
125.     /// </example>
126.     public static string ToMetric(this double input, MetricFormat formats = MetricFormat.UseSymbol, int? decimals = null)
127.     {
128.         if (double.IsNaN(input) || double.IsInfinity(input))
129.         {
130.             return input.ToString();
131.         }
132. 
133.         if (Math.Abs(input) < 1e-24)
134.         {
135.             return "0";
136.         }
137. 
138.         var isNegative = input < 0;
139.         input = Math.Abs(input);
140. 
141.         var exponent = (int)Math.Floor(Math.Log10(input));
142.         var metricExponent = exponent - (exponent % 3);
143. 
144.         if (metricExponent == 0)
145.         {
146.             var formatted = decimals.HasValue ? input.ToString($"F{decimals}") : input.ToString("G");
147.             return isNegative ? $"-{formatted}" : formatted;
148.         }
149. 
150.         var symbol = GetSymbolForExponent(metricExponent);
151.         if (symbol == null)
152.         {
153.             var fallback = input.ToString("G");
154.             return isNegative ? $"-{fallback}" : fallback;
155.         }
156. 
157.         var scaledValue = input / Math.Pow(10, metricExponent);
158.         var valueStr = decimals.HasValue ? scaledValue.ToString($"F{decimals}") : scaledValue.ToString("G4");
159. 
160.         var suffix = formats.HasFlag(MetricFormat.UseSymbol)
161.             ? SymbolStrings[symbol.Value]
162.             : $" {GetPrefixName(symbol.Value, formats)}";
163. 
164.         return isNegative ? $"-{valueStr}{suffix}" : $"{valueStr}{suffix}";
165.     }
