167.     /// <summary>
168.     /// Converts a metric string representation back to a number.
169.     /// </summary>
170.     /// <param name="input">The metric string to parse (e.g., "1.5k", "2.5 mega").</param>
171.     /// <returns>The numeric value represented by the metric string.</returns>
172.     /// <exception cref="ArgumentException">Thrown when the input is not a valid metric representation.</exception>
173.     /// <example>
174.     /// <code>
175.     /// "1.5k".FromMetric() => 1500
176.     /// "2.5M".FromMetric() => 2500000
177.     /// "100m".FromMetric() => 0.1
178.     /// </code>
179.     /// </example>
180.     public static double FromMetric(this string input)
181.     {
182.         ArgumentException.ThrowIfNullOrWhiteSpace(input);
183. 
184.         input = input.Trim();
185.         if (double.TryParse(input, out var directParse))
186.         {
187.             return directParse;
188.         }
189. 
190.         // Try symbol-based parsing first
191.         var lastChar = input[^1];
192.         if (UnitPrefixes.TryGetValue(lastChar, out var prefix))
193.         {
194.             var numericPart = input[..^1].Trim();
195.             if (double.TryParse(numericPart, out var value))
196.             {
197.                 var exponent = GetExponentForSymbol(lastChar);
198.                 return value * Math.Pow(10, exponent);
199.             }
200.         }
201. 
202.         // Try name-based parsing
203.         var nameInput = ReplaceNameBySymbol(input);
204.         if (nameInput != input)
205.         {
206.             return nameInput.FromMetric();
207.         }
208. 
209.         throw new ArgumentException($"Invalid metric numeral: '{input}'", nameof(input));
210.     }
211. 
212.     /// <summary>
213.     /// Determines whether the given string is a valid metric numeral.
214.     /// </summary>
215.     /// <param name="input">The string to validate.</param>
216.     /// <returns>true if the string can be parsed as a metric numeral; otherwise, false.</returns>
217.     public static bool IsValidMetricNumeral(this string input)
218.     {
219.         if (string.IsNullOrWhiteSpace(input))
220.         {
221.             return false;
222.         }
223. 
224.         input = input.Trim();
225.         if (double.TryParse(input, out _))
226.         {
227.             return true;
228.         }
229. 
230.         var index = input.Length - 1;
231.         var last = input[index];
232.         var isSymbol = UnitPrefixes.ContainsKey(last);
233.         return isSymbol && double.TryParse(input[..index], out _);
234.     }
