236.     /// <summary>
237.     /// Replaces a metric prefix name with its corresponding symbol in the input string.
238.     /// </summary>
239.     /// <param name="input">The string containing a metric prefix name.</param>
240.     /// <returns>The string with the prefix name replaced by its symbol.</returns>
241.     private static string ReplaceNameBySymbol(string input)
242.     {
243.         foreach (var kvp in NameToSymbol)
244.         {
245.             var idx = input.IndexOf(kvp.Key, StringComparison.Ordinal);
246.             if (idx >= 0)
247.             {
248.                 return string.Concat(input.AsSpan(0, idx), SymbolStrings[kvp.Value], input.AsSpan(idx + kvp.Key.Length));
249.             }
250.         }
251. 
252.         return input;
253.     }
