255.     private static char? GetSymbolForExponent(int exponent) =>
256.         ExponentToSymbol.TryGetValue(exponent, out var symbol) ? symbol : null;
257. 
258.     private static int GetExponentForSymbol(char symbol) =>
259.         symbol switch
260.         {
261.             'k' => 3, 'M' => 6, 'G' => 9, 'T' => 12, 'P' => 15, 'E' => 18, 'Z' => 21, 'Y' => 24,
262.             'm' => -3, 'μ' => -6, 'n' => -9, 'p' => -12, 'f' => -15, 'a' => -18, 'z' => -21, 'y' => -24,
263.             _ => 0
264.         };
265. 
266.     private static string GetPrefixName(char symbol, MetricFormat formats)
267.     {
268.         if (!UnitPrefixes.TryGetValue(symbol, out var prefix))
269.         {
270.             return SymbolStrings.TryGetValue(symbol, out var s) ? s : symbol.ToString();
271.         }
272. 
273.         return formats.HasFlag(MetricFormat.UseShortScale) ? prefix.ShortScaleWord : prefix.LongScaleWord;
274.     }
275. }
